const data = $input.first().json;
const body = data.body || data;
const drawings = body.drawings || [];

// Prefer large_thumbnail_url (smaller payload than full png_url) but fall back
const imageUrls = drawings
  .map(d => d.large_thumbnail_url || d.png_url || d.pdf_url)
  .filter(Boolean);

const context = drawings
  .map((d, i) => `Drawing ${i + 1}: ${d.drawing_number || '?'} — ${d.title || ''}`)
  .join('\n');

return {
  json: {
    project_id: body.project_id,
    project_name: body.project_name,
    drawings_count: drawings.length,
    imageUrlsCSV: imageUrls.join(','),
    context,
  }
};

const msg = $input.first().json;
const text = msg.content || (msg.message && msg.message.content) || msg.text || String(msg);

let trades;
try {
  const trimmed = String(text).trim();
  const cleaned = trimmed
    .replace(/^```(?:json)?\s*/, '')
    .replace(/\s*```$/, '');
  trades = JSON.parse(cleaned);
  if (!Array.isArray(trades)) throw new Error('Response was not a JSON array');
  trades = [...new Set(trades.map(t => String(t).trim()))].filter(Boolean).sort();
} catch (e) {
  throw new Error(`Could not parse OpenAI response as JSON array. Error: ${e.message}. Raw response: ${text}`);
}

const prep = $('Prepare').first().json;

return {
  json: {
    trades,
    drawings_analyzed: prep.drawings_count,
    model: 'gpt-4o',
    project_id: prep.project_id,
  }
};
